# celenity assets common environment variables

## CAUTION: Do NOT source this directly!
## Source 'env.sh' instead.

## Additionally, if you need to override any variables here, export them to your shell manually or use `env_override.sh`.
## Do NOT edit this file directly.

# If variables are defined with a custom `env_override.sh` file (located at the root project directory), let's use those
## These need to be set first, to ensure that they don't interfere with certain variables
readonly CEL_ASSETS_ENV_OVERRIDE="${CEL_ASSETS_ROOT}/env_override.sh"
if [[ -f "${CEL_ASSETS_ENV_OVERRIDE}" ]]; then
    source "${CEL_ASSETS_ENV_OVERRIDE}"
fi

# celenity assets

# Scripts directory
readonly CEL_ASSETS_SCRIPTS="${CEL_ASSETS_ROOT}/scripts"
export CEL_ASSETS_SCRIPTS

## celenity assets utilities
readonly CEL_ASSETS_UTILS="${CEL_ASSETS_SCRIPTS}/utilities.sh"
export CEL_ASSETS_UTILS

# Configuration files
readonly CEL_ASSETS_CONFIGS="${CEL_ASSETS_ROOT}/configs"
export CEL_ASSETS_CONFIGS

# Build directory
readonly CEL_ASSETS_BUILD="${CEL_ASSETS_ROOT}/build"
