# External sources directory
readonly CEL_ASSETS_EXTERNAL="${CEL_ASSETS_ROOT}/external"
export CEL_ASSETS_EXTERNAL

# External downloads/resources directory
readonly CEL_ASSETS_DOWNLOADS="${CEL_ASSETS_EXTERNAL}/downloads"
export CEL_ASSETS_DOWNLOADS

# Set our platform, OS, and architecture
readonly CEL_ASSETS_ENV_HELPERS="${CEL_ASSETS_SCRIPTS}/env_helpers.sh"
export CEL_ASSETS_ENV_HELPERS
source "${CEL_ASSETS_ENV_HELPERS}"

# Version info
readonly CEL_ASSETS_VERSIONS="${CEL_ASSETS_SCRIPTS}/versions.sh"
export CEL_ASSETS_VERSIONS

# Should we create a log file for get_sources.sh? (Default)
readonly CEL_ASSETS_LOG_SOURCES_DEFAULT=1
if [[ -z "${CEL_ASSETS_LOG_SOURCES+x}" ]]; then
    CEL_ASSETS_LOG_SOURCES="${CEL_ASSETS_LOG_SOURCES_DEFAULT}"
fi
readonly CEL_ASSETS_LOG_SOURCES
export CEL_ASSETS_LOG_SOURCES

# Should we create a log file for push_assets.sh? (Default)
