if [[ -z "${CEL_ASSETS_LOG_PUSH+x}" ]]; then
    CEL_ASSETS_LOG_PUSH="${CEL_ASSETS_LOG_PUSH_DEFAULT}"
fi
readonly CEL_ASSETS_LOG_PUSH
export CEL_ASSETS_LOG_PUSH

