if [[ -z "${CEL_ASSETS_LOG_DIR+x}" ]]; then
    CEL_ASSETS_LOG_DIR="${CEL_ASSETS_LOG_DIR_DEFAULT}"
fi
readonly CEL_ASSETS_LOG_DIR
export CEL_ASSETS_LOG_DIR

