fi
readonly CEL_ASSETS_UV_TOOLS
export CEL_ASSETS_UV_TOOLS

# Cipher suites
## (This enforces strong cipher suites - see ex. https://browserleaks.com/tls)
readonly CEL_ASSETS_CIPHERS_DEFAULT='TLS_AES_128_GCM_SHA256:TLS_CHACHA20_POLY1305_SHA256:TLS_AES_256_GCM_SHA384:ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384'
if [[ -z "${CEL_ASSETS_CIPHERS+x}" ]]; then
    CEL_ASSETS_CIPHERS="${CEL_ASSETS_CIPHERS_DEFAULT}"
fi
readonly CEL_ASSETS_CIPHERS
export CEL_ASSETS_CIPHERS

# If curl flags are added, this determines whether they should be appended to our default flags (default),
## or if they should override them entirely
readonly CEL_ASSETS_CURL_FLAGS_OVERRIDE_DEFAULT=0
if [[ -z "${CEL_ASSETS_CURL_FLAGS_OVERRIDE+x}" ]]; then
    CEL_ASSETS_CURL_FLAGS_OVERRIDE="${CEL_ASSETS_CURL_FLAGS_OVERRIDE_DEFAULT}"
fi
readonly CEL_ASSETS_CURL_FLAGS_OVERRIDE
export CEL_ASSETS_CURL_FLAGS_OVERRIDE

# curl flags
readonly CEL_ASSETS_CURL_FLAGS_DEFAULT="-q --disable --no-netrc -j -e "" -A "" -S --ciphers ${CEL_ASSETS_CIPHERS} --clobber --create-dirs --delegation none --disallow-username-in-url --doh-cert-status --ftp-create-dirs --ftp-ssl-control --junk-session-cookies --no-basic --no-ca-native --no-digest --no-doh-insecure --no-http0.9 --no-insecure --no-proxy-insecure --no-negotiate --no-ntlm --no-proxy-basic --no-proxy-ca-native --no-proxy-digest --no-proxy-insecure --no-proxy-ntlm --no-proxy-ssl-allow-beast --no-proxy-ssl-auto-client-cert --no-sessionid --no-skip-existing --no-ssl --no-ssl-allow-beast --no-ssl-auto-client-cert --no-ssl-no-revoke --no-ssl-revoke-best-effort --no-tls-earlydata --no-xattr --progress-meter --proto -all,https --proto-default https --proto-redir -all,https --referer "" --remove-on-error --show-error --ssl-reqd --tlsv1.2 --trace-time --user-agent "" --verbose"
if [[ -z "${CEL_ASSETS_CURL_FLAGS+x}" ]]; then
    CEL_ASSETS_CURL_FLAGS="${CEL_ASSETS_CURL_FLAGS_DEFAULT}"
elif [[ "${CEL_ASSETS_CURL_FLAGS_OVERRIDE}" == 1 ]]; then
    CEL_ASSETS_CURL_FLAGS="${CEL_ASSETS_CURL_FLAGS}"
else
    CEL_ASSETS_CURL_FLAGS="${CEL_ASSETS_CURL_FLAGS_DEFAULT} ${CEL_ASSETS_CURL_FLAGS}"
fi
readonly CEL_ASSETS_CURL_FLAGS
export CEL_ASSETS_CURL_FLAGS

# If s3cmd flags are added, this determines whether they should be appended to our default flags (default),
## or if they should override them entirely
readonly CEL_ASSETS_S3CMD_FLAGS_OVERRIDE_DEFAULT=0
if [[ -z "${CEL_ASSETS_S3CMD_FLAGS_OVERRIDE+x}" ]]; then
    CEL_ASSETS_S3CMD_FLAGS_OVERRIDE="${CEL_ASSETS_S3CMD_FLAGS_OVERRIDE_DEFAULT}"
fi
readonly CEL_ASSETS_S3CMD_FLAGS_OVERRIDE
export CEL_ASSETS_S3CMD_FLAGS_OVERRIDE

# s3cmd flags
readonly CEL_ASSETS_S3CMD_FLAGS_DEFAULT='--check-certificate --check-hostname --check-md5 --progress --ssl'
if [[ -z "${CEL_ASSETS_S3CMD_FLAGS+x}" ]]; then
    CEL_ASSETS_S3CMD_FLAGS="${CEL_ASSETS_S3CMD_FLAGS_DEFAULT}"
elif [[ "${CEL_ASSETS_S3CMD_FLAGS_OVERRIDE}" == 1 ]]; then
    CEL_ASSETS_S3CMD_FLAGS="${CEL_ASSETS_S3CMD_FLAGS}"
else
    CEL_ASSETS_S3CMD_FLAGS="${CEL_ASSETS_S3CMD_FLAGS_DEFAULT} ${CEL_ASSETS_S3CMD_FLAGS}"
fi
readonly CEL_ASSETS_S3CMD_FLAGS
export CEL_ASSETS_S3CMD_FLAGS

