# S3 access key
readonly CEL_ASSETS_S3_ACCESS_KEY_FILE_DEFAULT='/opt/celenity/celenity-assets-s3-access-key.txt'
if [[ -z "${CEL_ASSETS_S3_ACCESS_KEY_FILE+x}" ]]; then
